package com.terravow.reasoning;

import java.util.Objects;

/**
 * A stable identifier for a verified deterministic tool the reasoning layer invokes via Gemini
 * function calling (Req 2.2, 4.5, 6.2, 6.5).
 *
 * <p>Verified tools (EC formula, ERD summation, mass-preservation check, net-position arithmetic)
 * are executed by TerraVow, not free-generated by the model; the model orchestrates and the tool
 * emits the number. The identifier is a non-blank, opaque string.
 *
 * @param value a non-blank identifier of the tool
 *
 * @see ToolDeclaration
 * @see <a href="file:../../../../../.kiro/specs/terravow/requirements.md">Req 2.2, 4.5, 6.2,
 *      6.5</a>
 */
public record ToolId(String value) {

    /**
     * Validates that the identifier is present and non-blank.
     *
     * @throws NullPointerException     if {@code value} is {@code null}
     * @throws IllegalArgumentException if {@code value} is blank
     */
    public ToolId {
        Objects.requireNonNull(value, "ToolId value must not be null");
        if (value.isBlank()) {
            throw new IllegalArgumentException("ToolId value must not be blank");
        }
    }
}
